import React from 'react';
import { render, screen, waitFor, cleanup } from '@testing-library/react';
import '@testing-library/jest-dom/extend-expect';
import { act } from 'react-dom/test-utils';

// --- Module Mocks ---
// Mock child App to isolate ErrorBoundary behavior
jest.mock('../App', () => {
  const MockApp = () => <div data-testid="mock-app">Mock App Content</div>;
  MockApp.displayName = 'MockApp';
  return MockApp;
});

// Mock CSS import to prevent Jest from parsing CSS
jest.mock('../styles/index.css', () => ({}));

// Mock ReactDOM.createRoot to capture render calls
const mockRender = jest.fn();
const mockUnmount = jest.fn();
const mockRoot = { render: mockRender, unmount: mockUnmount };
jest.mock('react-dom/client', () => ({
  __esModule: true,
  createRoot: jest.fn(() => mockRoot),
}));

// Import target AFTER mocks are defined
import ErrorBoundary, { default as IndexEntry } from '../index';
import { createRoot } from 'react-dom/client';

// --- Test Utilities ---

/**
 * Creates a component that throws an error when rendered.
 * @param {boolean} shouldThrow - Whether to throw during render.
 * @returns {React.Component} A component that throws.
 */
const createThrowingComponent = (shouldThrow = true) => {
  const ThrowingComponent = () => {
    if (shouldThrow) {
      throw new Error('Intentional test error');
    }
    return <div data-testid="safe-component">Safe Content</div>;
  };
  ThrowingComponent.displayName = 'ThrowingComponent';
  return ThrowingComponent;
};

/**
 * Creates a stable component that renders children.
 * @param {React.ReactNode} children - Child elements.
 * @returns {React.Component} A stable wrapper component.
 */
const createStableComponent = (children) => {
  const StableComponent = () => <div data-testid="stable-wrapper">{children}</div>;
  StableComponent.displayName = 'StableComponent';
  return StableComponent;
};

// --- Test Suite: ErrorBoundary ---

describe('ErrorBoundary', () => {
  beforeEach(() => {
    // Suppress intentional console.error from React error boundary
    jest.spyOn(console, 'error').mockImplementation(() => {});
    mockRender.mockClear();
    mockUnmount.mockClear();
    createRoot.mockClear();
  });

  afterEach(() => {
    cleanup();
    jest.restoreAllMocks();
  });

  describe('Lifecycle & Rendering', () => {
    test('renders children when no error occurs', () => {
      const StableChild = () => <div data-testid="child-content">Child Rendered</div>;
      render(
        <ErrorBoundary>
          <StableChild />
        </ErrorBoundary>
      );
      expect(screen.getByTestId('child-content')).toBeInTheDocument();
      expect(screen.queryByTestId('error-fallback')).not.toBeInTheDocument();
    });

    test('renders fallback UI when child throws during render', () => {
      const ThrowingChild = createThrowingComponent(true);
      render(
        <ErrorBoundary>
          <ThrowingChild />
        </ErrorBoundary>
      );
      expect(screen.getByTestId('error-fallback')).toBeInTheDocument();
      expect(screen.getByText(/something went wrong/i)).toBeInTheDocument();
      expect(screen.queryByTestId('child-content')).not.toBeInTheDocument();
    });

    test('renders custom fallback when provided via prop', () => {
      const CustomFallback = () => <div data-testid="custom-fallback">Custom Error UI</div>;
      const ThrowingChild = createThrowingComponent(true);
      render(
        <ErrorBoundary fallback={<CustomFallback />}>
          <ThrowingChild />
        </ErrorBoundary>
      );
      expect(screen.getByTestId('custom-fallback')).toBeInTheDocument();
      expect(screen.queryByTestId('error-fallback')).not.toBeInTheDocument();
    });

    test('logs error details to console.error when boundary catches', () => {
      const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
      const ThrowingChild = createThrowingComponent(true);
      render(
        <ErrorBoundary>
          <ThrowingChild />
        </ErrorBoundary>
      );
      expect(consoleErrorSpy).toHaveBeenCalled();
      expect(consoleErrorSpy.mock.calls[0][0]).toContain('ErrorBoundary');
    });
  });

  describe('Error Recovery & State', () => {
    test('resets to normal rendering after error state is cleared', async () => {
      const TestComponent = () => {
        const [hasError, setHasError] = React.useState(false);
        if (hasError) {
          throw new Error('Simulated failure');
        }
        return (
          <button onClick={() => setHasError(true)} data-testid="trigger-error">
            Trigger Error
          </button>
        );
      };

      render(
        <ErrorBoundary>
          <TestComponent />
        </ErrorBoundary>
      );

      // Initial render succeeds
      expect(screen.getByTestId('trigger-error')).toBeInTheDocument();

      // Trigger error
      act(() => {
        screen.getByTestId('trigger-error').click();
      });

      // Fallback appears
      expect(screen.getByTestId('error-fallback')).toBeInTheDocument();

      // Simulate recovery (e.g., via retry button in fallback)
      const retryButton = screen.getByRole('button', { name: /retry/i });
      act(() => {
        retryButton.click();
      });

      // Component should re-render successfully
      await waitFor(() => {
        expect(screen.getByTestId('trigger-error')).toBeInTheDocument();
      });
    });

    test('does not trigger fallback for errors outside render lifecycle', () => {
      const EventHandlerComponent = () => {
        const handleClick = () => {
          throw new Error('Event handler error');
        };
        return <button onClick={handleClick} data-testid="event-button">Click</button>;
      };

      render(
        <ErrorBoundary>
          <EventHandlerComponent />
        </ErrorBoundary>
      );

      // Event handler errors should NOT be caught by ErrorBoundary
      expect(() => {
        act(() => {
          screen.getByTestId('event-button').click();
        });
      }).toThrow('Event handler error');

      // Fallback should not appear
      expect(screen.queryByTestId('error-fallback')).not.toBeInTheDocument();
    });
  });

  describe('Edge Cases', () => {
    test('handles null children gracefully', () => {
      render(<ErrorBoundary>{null}</ErrorBoundary>);
      expect(screen.queryByTestId('error-fallback')).not.toBeInTheDocument();
    });

    test('handles multiple children where one throws', () => {
      const ThrowingChild = createThrowingComponent(true);
      const StableChild = () => <div data-testid="stable-child">Stable</div>;
      render(
        <ErrorBoundary>
          <StableChild />
          <ThrowingChild />
        </ErrorBoundary>
      );
      expect(screen.getByTestId('error-fallback')).toBeInTheDocument();
      expect(screen.queryByTestId('stable-child')).not.toBeInTheDocument();
    });

    test('preserves error boundary state across re-renders', () => {
      const ThrowingChild = createThrowingComponent(true);
      const { rerender } = render(
        <ErrorBoundary>
          <ThrowingChild />
        </ErrorBoundary>
      );
      expect(screen.getByTestId('error-fallback')).toBeInTheDocument();

      // Re-render with different children
      rerender(
        <ErrorBoundary>
          <div data-testid="new-child">New Child</div>
        </ErrorBoundary>
      );
      // Boundary should still show fallback (state preserved)
      expect(screen.getByTestId('error-fallback')).toBeInTheDocument();
      expect(screen.queryByTestId('new-child')).not.toBeInTheDocument();
    });
  });
});

// --- Test Suite: Index Entry (Root Render) ---

describe('IndexEntry (Root Render)', () => {
  beforeEach(() => {
    mockRender.mockClear();
    mockUnmount.mockClear();
    createRoot.mockClear();
    // Reset DOM
    document.body.innerHTML = '<div id="root"></div>';
  });

  afterEach(() => {
    cleanup();
    jest.restoreAllMocks();
  });

  test('invokes createRoot with the root DOM element', () => {
    IndexEntry();
    expect(createRoot).toHaveBeenCalledTimes(1);
    const rootElement = createRoot.mock.calls[0][0];
    expect(rootElement).toBeInstanceOf(HTMLElement);
    expect(rootElement.id).toBe('root');
  });

  test('invokes root.render with an ErrorBoundary-wrapped App', () => {
    IndexEntry();
    expect(mockRender).toHaveBeenCalledTimes(1);
    const renderedElement = mockRender.mock.calls[0][0];
    expect(renderedElement.type).toBe(ErrorBoundary);
    // Verify App is wrapped inside ErrorBoundary
    expect(renderedElement.props.children.type.name).toBe('MockApp');
  });

  test('invokes root.render with StrictMode wrapper', () => {
    IndexEntry();
    const renderedElement = mockRender.mock.calls[0][0];
    expect(renderedElement.type).toBe(React.StrictMode);
    // Verify ErrorBoundary is inside StrictMode
    expect(renderedElement.props.children.type).toBe(ErrorBoundary);
  });

  test('does not throw when root element is missing', () => {
    document.body.innerHTML = '';
    expect(() => IndexEntry()).not.toThrow();
    expect(createRoot).not.toHaveBeenCalled();
  });

  test('handles multiple invocations gracefully', () => {
    IndexEntry();
    IndexEntry();
    expect(createRoot).toHaveBeenCalledTimes(2);
    expect(mockRender).toHaveBeenCalledTimes(2);
  });

  test('unmounts previous root on hot module replacement', () => {
    // Simulate HMR by calling the module's accept handler
    const hotAccept = jest.fn();
    if (module.hot) {
      module.hot.accept = hotAccept;
    }
    IndexEntry();
    // Trigger HMR cleanup if implemented
    if (typeof module.hot !== 'undefined' && module.hot.dispose) {
      module.hot.dispose(() => {
        mockUnmount();
      });
    }
    expect(mockUnmount).toHaveBeenCalled();
  });
});

